// B"H
// build-bundle.mjs — heichel shell CSS bundler (site QA, 2026-11-10).
//
// The heichel shell template linked 12 stylesheets whose @import closure
// is 211 files / ~413KB — 211 render-blocking requests on every Torah
// index, section and series page. This builder folds the closure into ONE
// file in exact cascade order, following browser @import semantics: only
// @imports that lead their file are honored; a later @import is one
// browsers drop, so the builder drops it too and says so. No relative
// asset url()s exist anywhere in the closure (verified), so plain
// concatenation cannot break asset paths.
//
// Usage: node build-bundle.mjs   (run from geelooy/heichelos)
// Output: heichel-bundle.css next to this script. The template pins it by
// content hash, so nginx serves it immutable.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const heichelosDir = dirname(fileURLToPath(import.meta.url));
const geelooyDir = resolve(heichelosDir, '..');
const outPath = join(heichelosDir, 'heichel-bundle.css');

// The shell template's original 12 links, frozen in cascade order. Since
// the bundle landed, the template links only heichel-bundle.css, so the
// builder carries the list itself. Order IS the cascade — do not reorder.
const links = [
	'/style/awtsmoos-scroll-sovereignty.css',
	'/style/heichelos/heichel/index.css',
	'/style/geelooy-system/index.css',
	'/style/civilization/core-tokens.css',
	'/style/civilization/core-base.css',
	'/style/civilization/core-components.css',
	'/style/civilization/heichel-institution.css',
	'/style/civilization/heichel-content.css',
	'/style/civilization/heichel-responsive.css',
	'/style/heichelos/heichel/cosmic-profile/index.css',
	'/style/heichelos/heichel/premium/law8/ikar-tanach-reader.css',
	'/heichelos/heichel-polish-law8.css'
];

const warnings = [];
const seen = new Set();
const parts = [];

function stripCommentsState(line, state) {
	let out = '';
	for (let i = 0; i < line.length; i++) {
		if (state.inComment) {
			if (line[i] === '*' && line[i + 1] === '/') { state.inComment = false; i++; out += '  '; } else out += ' ';
		} else if (line[i] === '/' && line[i + 1] === '*') {
			state.inComment = true; i++; out += '  ';
		} else out += line[i];
	}
	return out;
}

function expand(absPath) {
	const rel = relative(geelooyDir, absPath);
	if (seen.has(absPath)) { warnings.push(`duplicate skipped (already in cascade): ${rel}`); return; }
	seen.add(absPath);
	if (!existsSync(absPath)) { warnings.push(`MISSING @import target (browser 404s it, contributes nothing): ${rel}`); return; }
	const text = readFileSync(absPath, 'utf8');
	const state = { inComment: false };
	let leading = true;
	const body = [];
	for (const line of text.split('\n')) {
		const code = stripCommentsState(line, state);
		const imp = /^\s*@import\s+(?:url\(\s*)?["']?([^"')\s;]+)["']?\s*\)?\s*;?\s*$/.exec(code);
		if (imp && !state.inComment) {
			const target = imp[1].split('?')[0];
			if (/^https?:/.test(target)) { warnings.push(`external @import kept as-is (INVALID mid-bundle, must fix): ${rel} -> ${target}`); body.push(line); leading = false; continue; }
			if (!leading) { warnings.push(`late @import dropped (browsers drop it too): ${rel} -> ${target}`); continue; }
			const targetAbs = target.startsWith('/')
				? join(geelooyDir, target)
				: resolve(dirname(absPath), target);
			expand(targetAbs);
			continue;
		}
		if (/^\s*@charset\b/.test(code)) continue;
		if (code.trim() && !/^\s*@/.test(code)) leading = false;
		body.push(line);
	}
	parts.push(`\n/* ==== ${rel} ==== */\n` + body.join('\n'));
}

for (const href of links) expand(join(geelooyDir, href.replace(/^\//, '')));

const banner = `@charset "UTF-8";\n/* B"H — GENERATED by heichelos/build-bundle.mjs. Do not edit by hand.\n * One bundle for the heichel shell pages, folded from ${seen.size} source sheets in exact\n * cascade order. Sources stay on disk; edit them and re-run the builder. */\n`;
writeFileSync(outPath, banner + parts.join('\n'));
console.log(`wrote ${relative(geelooyDir, outPath)} from ${seen.size} files, ${links.length} template links`);
for (const w of warnings) console.log('WARN:', w);
